// Summary page stub
import React, {
    useEffect,
    useState
} from 'react';
import {
    useNavigate
} from 'react-router-dom';

function Summary() {
    const [summary, setSummary] = useState('');
    const [sources, setSources] = useState([]);
    const [confidence, setConfidence] = useState('');
    const [conditions, setConditions] = useState([]);
    const [medications, setMedications] = useState([]);
    const [toast, setToast] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        const data = localStorage.getItem('summary');
        if (data) {
            const parsed = JSON.parse(data);
            setSummary(parsed.summary);
            setSources(parsed.sources);
            setConfidence(parsed.confidence);
            // Try to extract conditions/medications from summary string
            if (parsed.summary) {
                const condMatch = parsed.summary.match(/Conditions: ([^;]*)/);
                const medMatch = parsed.summary.match(/Medications: ([^;]*)/);
                setConditions(condMatch && condMatch[1] ? condMatch[1].split(',').map(s => s.trim()).filter(Boolean) : []);
                setMedications(medMatch && medMatch[1] ? medMatch[1].split(',').map(s => s.trim()).filter(Boolean) : []);
            }
        }
    }, []);

    const handleCopy = () => {
        navigator.clipboard.writeText(summary);
        setToast('Summary copied to clipboard!');
        setTimeout(() => setToast(''), 2000);
    };

    const handleDownload = () => {
        const element = document.createElement('a');
        const file = new Blob([summary], {
            type: 'text/plain'
        });
        element.href = URL.createObjectURL(file);
        element.download = 'medical_summary.txt';
        document.body.appendChild(element);
        element.click();
        document.body.removeChild(element);
    };

    const handleClear = () => {
        localStorage.removeItem('summary');
        navigate('/dashboard');
    };

    return ( <
            div >
            <
            h2 > Medical History Summary < /h2> <
            p > {
                summary
            } < /p> <
            span style = {
                {
                    background: '#e0e0e0',
                    padding: '4px 8px',
                    borderRadius: '8px',
                    marginRight: '8px'
                }
            } > < strong > Confidence: < /strong> {confidence}</span >
            <
            div style = {
                {
                    margin: '10px 0'
                }
            } >
            <
            button onClick = {
                handleCopy
            } > Copy Summary < /button> <
            button onClick = {
                handleDownload
            }
            style = {
                {
                    marginLeft: '8px'
                }
            } > Download Summary < /button> <
            button onClick = {
                handleClear
            }
            style = {
                {
                    marginLeft: '8px'
                }
            } > Clear & Return < /button> < /
            div > {
                toast && ( <
                    div style = {
                        {
                            color: 'green',
                            marginBottom: '10px'
                        }
                    } > {
                        toast
                    } < /div>
                )
            } {
                conditions.length > 0 && ( <
                        div style = {
                            {
                                margin: '10px 0'
                            }
                        } >
                        <
                        strong > Extracted Conditions: < /strong> <
                        ul > {
                            conditions.map((c, i) => ( < li key = {
                                        i
                                    } > {
                                        c
                                    } < /li>))}</ul >
                                    <
                                    /div>
                                )
                            } {
                                medications.length > 0 && ( <
                                    div style = {
                                        {
                                            margin: '10px 0'
                                        }
                                    } >
                                    <
                                    strong > Extracted Medications: < /strong> <
                                    ul > {
                                        medications.map((m, i) => ( < li key = {
                                                    i
                                                } > {
                                                    m
                                                } < /li>))}</ul >
                                                <
                                                /div>
                                            )
                                        } <
                                        ul > {
                                            sources.map((src, idx) => ( <
                                                li key = {
                                                    idx
                                                } > < a href = {
                                                    src
                                                }
                                                target = "_blank"
                                                rel = "noopener noreferrer" > Source {
                                                    idx + 1
                                                } < /a></li >
                                            ))
                                        } <
                                        /ul> <
                                        p style = {
                                            {
                                                color: 'gray',
                                                fontSize: 'small'
                                            }
                                        } > Disclaimer: This summary is not diagnostic.For informational purposes only. < /p> < /
                                        div >
                                    );
                                }

                                export default Summary;
